namespace SpinalShatter.Scripts.UI;

[Tool]
public partial class InventoryHUDItem : Control
{
    public enum HUDFrameType
    {
        Primary,
        Secondary,
        Automatic,
        Stat
    }

    // This dictionary would be populated with actual Texture2D resources.
    // For now, it's a placeholder. The logic to use it is implemented.
    private static readonly Dictionary<HUDFrameType, Texture2D> FrameTextures = new();

    private HUDFrameType _frameType;

    [Export]
    public HUDFrameType FrameType
    {
        get => _frameType;
        set
        {
            _frameType = value;
            UpdateFrameTexture();
        }
    }

    private TextureRect _frameRect;
    private TextureRect _iconRect;
    private Label _rankLabel;

    public override void _Ready()
    {
        _frameRect = GetNode<TextureRect>("FrameRect");
        _iconRect = GetNode<TextureRect>("IconRect");
        _rankLabel = GetNode<Label>("RankLabel");
    }

    public void UpdateDisplay(ShopItemData itemData, int rank)
    {
        if (itemData == null)
        {
            _iconRect.Texture = null;
            _rankLabel.Text = "";
            Visible = false;
        }
        else
        {
            _iconRect.Texture = itemData.ItemIcon?.GetFrameTexture("default", 0);
            _rankLabel.Text = IntToRoman(rank);
            Visible = true;
        }
    }

    private void UpdateFrameTexture()
    {
        if (_frameRect != null && FrameTextures.TryGetValue(_frameType, out Texture2D texture))
        {
            _frameRect.Texture = texture;
        }
    }

    private static string IntToRoman(int num)
    {
        if (num < 1) return "";
        if (num >= 40) return "XL"; // Unlikely but for safety

        int[] values = { 10, 9, 5, 4, 1 };
        string[] romanLiterals = { "X", "IX", "V", "IV", "I" };

        var roman = new StringBuilder();
        for (int i = 0; i < values.Length; i++)
        {
            while (num >= values[i])
            {
                num -= values[i];
                roman.Append(romanLiterals[i]);
            }
        }
        return roman.ToString();
    }
}

