		_bonusContainer = GetNode<VBoxContainer>("DirectorDisplay/MarginContainer/Bonus_VBoxContainer");
		_timeBonusTextValue = GetNode<RichTextLabel>("%TimeBonus_TextValue");
		_lifeBonusTextValue = GetNode<RichTextLabel>("%LifeBonus_TextValue");

		_roomEnemyLabels["North"] = GetNode<RichTextLabel>("%NorthTextValue");
		_roomEnemyLabels["East"] = GetNode<RichTextLabel>("%EastTextValue");
		_roomEnemyLabels["South"] = GetNode<RichTextLabel>("%SouthTextValue");
		_roomEnemyLabels["West"] = GetNode<RichTextLabel>("%WestTextValue");
		// --- End UI Initialization ---

		RoomManager.Instance.SafeSubscribe<LevelRoom>(RoomManager.SignalName.CurrentRoomChanged, OnCurrentRoomChanged);

		// Immediately handle the starting room if it's already set
		OnCurrentRoomChanged(RoomManager.Instance.CurrentRoom);

		// Initial UI state
		ResetAllUI();
	}

	public override void _Process(double delta)
	{
		if (IsRoundStarted && RoundTimer != null)
		{
			var time = TimeSpan.FromSeconds(RoundTimer.TimeLeft);
			int currentWaveNumber = _wavesCompletedThisRound + 1;

			// Update Timer
			_timerLabel.Text = time.ToString(@"mm\:ss");

			// Update Wave MinMaxValuesLabel
			_waveMinMaxLabel.TextCurrent = (_wavesCompletedThisRound >= wavesPerRound ? wavesPerRound : currentWaveNumber).ToString();
			_waveMinMaxLabel.TextMaximum = wavesPerRound.ToString();

			// Update Round Text Value
			_roundTextValue.Text = CurrentRound.ToString();

			// Update Active Room Enemy Count
			_activeEnemyCountTextValue.Text = _activeRoom?.EnemyCount.ToString() ?? "0";

			// Update Room-specific Breakdown
			var nodesInCombatGroup = GetTree().GetNodesInGroup("OutsideHub");
			foreach (var node in nodesInCombatGroup)
			{
				if (node is LevelRoom room)
				{
					if (_roomEnemyLabels.TryGetValue(room.Name, out var label))
					{
						int totalEnemiesForWave = (IsRoundStarted && room == _roundInProgressRoom) ? _enemiesThisWave : 0;
						label.Text = $"{room.EnemyCount} / {totalEnemiesForWave}";
					}
				}
			}
		}
	}

	private void InitializeLevelReferences()
	{
		Reset();

		_hubDoors.Clear();
		_combatRooms.Clear();

		// Find and register all HUB doors
		foreach (var node in GetTree().GetNodesInGroup("Hub"))
		{
			if (node is Door door)
			{
				if (!_hubDoors.TryAdd(door.DoorDirection, door))
				{
					DebugManager.Warning($"InitializeLevelReferences: Duplicate hub door found for direction {door.DoorDirection}");
					continue;
				}
				door.SafeSubscribe(Door.SignalName.PlayerDoorShut, OnHubDoorShut);
			}
		}

		// Find and register all COMBAT rooms
		foreach (var node in GetTree().GetNodesInGroup("OutsideHub"))
		{
			if (node is LevelRoom room)
			{
				if (!_combatRooms.TryAdd(room.RoomDirection, room))
				{
					DebugManager.Warning($"InitializeLevelReferences: Duplicate combat room found for direction {room.RoomDirection}");
				}
			}
		}

		CheckAllNodesReady();
	}

	private void CheckAllNodesReady()
	{
		// Once all doors and rooms have been found, initialize the doors for the first time.
		if (_hubDoors.Count == 4 && _combatRooms.Count == 4)
		{
			foreach (var keyValuePair in _hubDoors)
			{
				keyValuePair.Value.InstantClose();
			}
			foreach (var keyValuePair in _combatRooms)
			{
				keyValuePair.Value.LevelDoor.InstantOpen();
			}
			SelectNewDoors();
		}
	}

	public void Reset()
	{
		// Reset state variables
		CurrentRound = 1;
		TotalWavesCompleted = 0;
		IsRoundStarted = false;
		IsRoundCompleted = false;
		_wavesCompletedThisRound = 0;
		_enemiesThisWave = 0;
		_roundInProgressRoom = null;
		_lastCompletedRoomDirection = null;

		// Safely unsubscribe from _activeRoom's events before nulling it
		if (_activeRoom != null && GodotObject.IsInstanceValid(_activeRoom))
		{
			_activeRoom.SafeUnsubscribe(LevelRoom.SignalName.WaveCleared, OnWaveCleared);
		}
		_activeRoom = null;

		// Reset timers
		RoundTimer.Stop();

		// Reset UI
		ResetAllUI();
	}

	public void SetPlayer(PlayerBody playerInstance)
	{
		// If the same player instance is being set, there's nothing to do.
		if (playerInstance == player)
		{
			return;
		}

		// This is now the main entry point for setting up the director for a level
		InitializeLevelReferences();

		// Unsubscribe from old player if it exists and is valid
		if (player != null && GodotObject.IsInstanceValid(player))
		{
			player.HealthComponent.SafeUnsubscribe(HealthComponent.SignalName.OutOfHealth, ProcessRoundLostState);
			player.SafeUnsubscribe(PlayerBody.SignalName.PlayerDied, ShowGameOverMenu);
		}

		player = playerInstance;

		if (player == null)
		{
			DebugManager.Error("WaveDirector: Attempted to set player with a null instance!");
			return;
		}

		// Subscribe to new player
		player.HealthComponent.SafeSubscribe(HealthComponent.SignalName.OutOfHealth, ProcessRoundLostState);
		player.SafeSubscribe(PlayerBody.SignalName.PlayerDied, ShowGameOverMenu);
	}

	private void OnCurrentRoomChanged(LevelRoom newRoom)
	{
		if (_activeRoom != null && GodotObject.IsInstanceValid(_activeRoom))
		{
			_activeRoom.SafeUnsubscribe(LevelRoom.SignalName.WaveCleared, OnWaveCleared);
		}

		_activeRoom = newRoom;

		if (_activeRoom != null)
		{
			_activeRoom.SafeSubscribe(LevelRoom.SignalName.WaveCleared, OnWaveCleared);
		}
	}

	public void StartRound(LevelRoom room)
	{
		if (player == null)
		{
			DebugManager.Error("WaveDirector: Player instance is null. Cannot start round.");
			return;
		}

		foreach (var hubDoor in _hubDoors.Values)
		{
			hubDoor.SystemClose();
		}

		_wavesCompletedThisRound = -1;
		_roundInProgressRoom = room;

		IsRoundStarted = true;
		IsRoundCompleted = false;
		startingPlayerHealth = player.HealthComponent.CurrentPercent;
		RoundTimer.Start();
		StartNextWave();
		_wavesCompletedThisRound = 0;

		_timerLabel.Visible = true;
		_activeEnemyCountTextValue.Visible = true;
		_activeEnemyCountHBoxContainer.Visible = true;
		_roomLabelsVBoxContainer.Visible = true;
		_waveRoundContainer.Visible = true;
	}

	private void StartNextWave()
	{
		if (_wavesCompletedThisRound >= wavesPerRound)
		{
			OnRoundWon();
			return;
		}

		var budget = CalculateBudget();
		var enemies = GenerateEnemyList(budget);
		_enemiesThisWave = enemies.Count;
		_activeRoom.StartSpawning(enemies);
	}

	private void OnWaveCleared()
	{
		TotalWavesCompleted++;
		_wavesCompletedThisRound++;
		GetTree().CreateTimer(3.0f).Timeout += StartNextWave;
	}

	private void OnRoundWon()
	{
		IsRoundStarted = false;
		IsRoundCompleted = true;

		if (_roundInProgressRoom != null)
		{
			_roundInProgressRoom.OnRoundCompletion();
			_lastCompletedRoomDirection = _roundInProgressRoom.RoomDirection;

			if (_hubDoors.TryGetValue(_roundInProgressRoom.RoomDirection, out var doorToOpen))
			{
				doorToOpen.SystemOpen();
			}
		}
		_roundInProgressRoom = null;

		endingPlayerHealth = player.HealthComponent.CurrentHealth;

		double timeLeft = RoundTimer.TimeLeft;
		RoundTimer.Stop();

		moneyTimeBonus = (int)(moneyGivenPerSecondLeft * timeLeft * DifficultyMultipliers[SelectedDifficulty]);
		player.ReceiveMoney(moneyTimeBonus);

		moneyHealthBonus =
			(int)(moneyGivenPerHealthLeft * endingPlayerHealth * DifficultyMultipliers[SelectedDifficulty]);
		player.ReceiveMoney(moneyHealthBonus);

		CurrentRound++;
		if (wavesPerRound < 5)
		{
			wavesPerRound++;
		}

		GD.Print($"Round {CurrentRound - 1} won! Return to Hub.");

		_victoryLabel.Visible = true;
		_defeatLabel.Visible = false;
		_bonusContainer.Visible = true;
		_timerLabel.Visible = false;
		_activeEnemyCountTextValue.Visible = false;
		_activeEnemyCountHBoxContainer.Visible = false;
		_roomLabelsVBoxContainer.Visible = false;
		_waveRoundContainer.Visible = false;

		_timeBonusTextValue.Text = moneyTimeBonus.ToString();
		_lifeBonusTextValue.Text = moneyHealthBonus.ToString();

		EmitRoundWon();
	}

	private void OnHubDoorShut()
	{
		if (!IsRoundStarted && IsRoundCompleted && RoomManager.Instance.CurrentRoom is { IsCentralHub: true })
		{
			ResetAllUI();
			SelectNewDoors();
			IsRoundCompleted = false;
		}
	}

	private void SelectNewDoors()
	{
		var allDirections = new Array<CardinalDirection>(
			System.Enum.GetValues(typeof(CardinalDirection)).Cast<CardinalDirection>()
		);

		if (_lastCompletedRoomDirection.HasValue)
		{
			allDirections.Remove(_lastCompletedRoomDirection.Value);
		}

		var rng = new RandomNumberGenerator();
		rng.Randomize();
		allDirections.Shuffle();

		var doorsToOpen = new Array<CardinalDirection>();
		for(int i = 0; i < 2 && i < allDirections.Count; i++)
		{
			doorsToOpen.Add(allDirections[i]);
		}

		// DebugManager.Debug($"Selecting new doors. Last completed: {_lastCompletedRoomDirection?.ToString() ?? "None"}. Opening: {string.Join(", ", doorsToOpen.Select(d => d.ToString()).ToArray())}");

		foreach (var direction in System.Enum.GetValues(typeof(CardinalDirection)).Cast<CardinalDirection>())
		{
			if (_hubDoors.TryGetValue(direction, out var door))
			{
				if (doorsToOpen.Contains(direction))
				{
					door.SystemOpen();
				}
				else
				{
					door.SystemClose();
				}
			}
			else
			{
				 DebugManager.Warning($"SelectNewDoors: Could not find door for direction {direction}.");
			}
		}
	}

	private void ProcessRoundLostState()
	{
		if (!IsRoundStarted && RoundTimer.IsStopped()) return;

		ResetAllUI();
		IsRoundStarted = false;
		IsRoundCompleted = false;
		_roundInProgressRoom = null;

		endingPlayerHealth = player.HealthComponent.CurrentHealth;
		RoundTimer.Stop();
		GD.Print("Round Lost!");

		_victoryLabel.Visible = false;
		_defeatLabel.Visible = true;
		_bonusContainer.Visible = false;
		_timerLabel.Visible = false;
		_activeEnemyCountTextValue.Visible = false;
		_activeEnemyCountHBoxContainer.Visible = false;
		_roomLabelsVBoxContainer.Visible = false;
		_waveRoundContainer.Visible = false;

		_timeBonusTextValue.Text = "0";
		_lifeBonusTextValue.Text = "0";
	}

	private void ShowGameOverMenu()
	{
		if (_levelLostMenuScene != null)
		{
			if (PlayerBody.Instance.ControlRoot.FindChild("LevelLostMenu", recursive: false) == null)
			{
				var levelLostMenu = _levelLostMenuScene.Instantiate();
				levelLostMenu.Name = "LevelLostMenu";
				levelLostMenu.Connect("main_menu_pressed", Callable.From(OnMainMenuPressed));
				PlayerBody.Instance.ControlRoot.AddChild(levelLostMenu);
			}
		}
		else
		{
			DebugManager.Error("WaveDirector: _levelLostMenuScene is not assigned!");
		}
	}

	private void OnMainMenuPressed()
	{
		GetTree().Paused = false;
		if (_mainMenuScene != null)
		{
			GetNode<Node>("/root/SceneLoader").Call("load_scene", _mainMenuScene.ResourcePath);
		}
		else
		{
			DebugManager.Error("WaveDirector: _mainMenuScene is not assigned!");
		}
	}

	public void OnRoundLost()
	{
		ProcessRoundLostState();
		ShowGameOverMenu();
	}

	private float CalculateBudget()
	{
		float difficultyMultiplier = difficultyMultipliers[SelectedDifficulty];
		float roundBonus = (CurrentRound - 1) * budgetIncreasePerRound;
		float waveBonus = TotalWavesCompleted * budgetIncreasePerWave;

		return (baseBudget + roundBonus + waveBonus) * difficultyMultiplier;
	}

	private Array<PackedScene> GenerateEnemyList(float budget)
	{
		var enemiesToSpawn = new Array<PackedScene>();
		if (_enemyDataToSceneMap.Count == 0)
		{
			GD.PrintErr("WaveDirector: No available enemies to spawn!");
			return enemiesToSpawn;
		}

		var availableEnemies = _enemyDataToSceneMap
							  .Select(pair => new
							   {
								   Data = pair.Key, Scene = pair.Value,
								   Cost = pair.Key.BaseCost * enemyStrengthMultipliers[pair.Key.Rank]
							   })
							  .Where(e => e.Cost > 0)
							  .ToList();

		if (!availableEnemies.Any())
		{
			GD.PrintErr("WaveDirector: No available enemies with a cost greater than 0!");
			return enemiesToSpawn;
		}

		while (budget > 0 && availableEnemies.Any(e => e.Cost <= budget))
		{
			var affordableEnemies = availableEnemies.Where(e => e.Cost <= budget).ToList();
			if (!affordableEnemies.Any()) break;

			var chosenEnemy = affordableEnemies[GD.RandRange(0, affordableEnemies.Count - 1)];

			enemiesToSpawn.Add(chosenEnemy.Scene);
			budget -= chosenEnemy.Cost;
		}

		return enemiesToSpawn;
	}

	private void OnRoundTimerTimeout()
	{
		// Play timer alarm sound
	}

	private void ResetAllUI()
	{
		_timerLabel.Visible = false;
		_activeEnemyCountTextValue.Visible = false;
		_activeEnemyCountHBoxContainer.Visible = false;
		_roomLabelsVBoxContainer.Visible = false;
		_waveRoundContainer.Visible = false;
		_victoryLabel.Visible = false;
		_defeatLabel.Visible = false;
		_bonusContainer.Visible = false;
	}
}

using Godot;
using Godot.Collections;
using System.Collections.Generic;
using System.Linq;
using Elythia;

namespace SpinalShatter;

public partial class LevelRoom : Node3D
{
	[Signal]
	public delegate void PlayerEnteredEventHandler(LevelRoom room);

	[Signal]
	public delegate void PlayerExitedEventHandler(LevelRoom room);

	[Signal]
	public delegate void WaveClearedEventHandler();

	[Export] public CardinalDirection RoomDirection { get; set; }
	[Export] private bool alwaysShow = false;
	public bool IsCentralHub { get; set; } = false;

	private Array<EnemySpawner> _spawners;
	private Area3D _triggerVolume;
	private Door levelDoor;

	private bool _spawningFinished = false;

	public bool IsActive { get; private set; }
	public List<Enemy> EnemiesInRoom { get; private set; } = new();
	public int EnemyCount => EnemiesInRoom.Count;

	public Door LevelDoor => levelDoor;

	public override void _Ready()
	{
		// Self-register with WaveDirector if this is a combat room
		IsCentralHub = IsInGroup("Hub");
		if (!IsCentralHub)
		{
			levelDoor = GetNode<Door>("Door");
			levelDoor.PlayerDoorShut += OnLevelDoorShut;
		}

		// Common logic for all rooms below
		_triggerVolume = GetNode<Area3D>("%LevelRegion");
		if (_triggerVolume != null)
		{
			_triggerVolume.BodyEntered += OnBodyEntered;
			_triggerVolume.BodyExited += OnBodyExited;
		}

		var spawnerRoot = GetNode<Node3D>("%Spawners");

		_spawners ??= new Array<EnemySpawner>();
		foreach (var child in spawnerRoot.GetChildren())
		{
			if (child is EnemySpawner spawner)
			{
				_spawners.Add(spawner);
			}
		}

		foreach (var spawner in _spawners)
		{
			spawner.SpawningFinished += OnSpawningFinished;
		}

		// Find any enemies that are pre-placed in the room in the editor
		FindEnemiesRecursively(this);

		RoomManager.Instance.RegisterRoom(this);
	}

	public void StartSpawning(Array<PackedScene> enemies)
	{
		if (_spawners.Count == 0)
		{
			GD.PrintErr($"LevelRoom '{Name}' has no spawners, cannot start spawning.");
			return;
		}

		_spawningFinished = false;

		// Initialize pools for all unique scenes on all potential spawners
		var uniqueScenes = enemies.Distinct();
		foreach (var spawner in _spawners)
		{
			spawner.InitializePools(uniqueScenes);
		}

		// Pick a single random spawner to handle the whole wave
		var chosenSpawner = _spawners[(int)(GD.Randi() % _spawners.Count)];
		chosenSpawner.StartSpawningWave(enemies);
	}

	private void OnSpawningFinished()
	{
		_spawningFinished = true;
		CheckWaveCleared();
	}

	private void OnLevelDoorShut()
	{
		if (WaveDirector.Instance.IsRoundStarted) return;
		WaveDirector.Instance.StartRound(this);
	}

	private void OnEnemyDied(Enemy who)
	{
		// DebugManager.Debug($"LevelRoom: {Name} OnEnemyDied called for {who.Name}.");
		UnregisterEnemy(who);
	}

	private void CheckWaveCleared()
	{
		if (!IsActive || !_spawningFinished)
		{
			return;
		}

		// If spawning is finished and no enemies are left, the wave is cleared
		if (EnemiesInRoom.Count == 0)
		{
			EmitSignalWaveCleared();
			GD.Print("Wave Cleared!");
		}
	}

	private void FindEnemiesRecursively(Node node)
	{
		foreach (var child in node.GetChildren())
		{
			if (child is Enemy enemy)
			{
				RegisterEnemy(enemy);
			}
			else
			{
				FindEnemiesRecursively(child);
			}
		}
	}

	public void RegisterEnemy(Enemy enemy)
	{
		if (EnemiesInRoom.Contains(enemy)) return;
		EnemiesInRoom.Add(enemy);
		enemy.AssociatedRoom = this;
		enemy.EnemyDied += OnEnemyDied;

		// DebugManager.Debug($"LevelRoom: {Name} Registered enemy {enemy.Name}. Total enemies: {_enemiesInRoom.Count}");
	}

	public void UnregisterEnemy(Enemy enemy)
	{
		if (EnemiesInRoom.Remove(enemy))
		{
			enemy.EnemyDied -= OnEnemyDied;

			// DebugManager.Debug($"LevelRoom: {Name} Unregistered enemy {enemy.Name}. Total enemies: {_enemiesInRoom.Count}");
			CheckWaveCleared();
		}
	}

	private void OnBodyEntered(Node3D body)
	{
		//DebugManager.Trace($"{body.Name} entered {this.Name}");
		if (body is PlayerBody)
		{
			RoomManager.Instance.RegisterRoom(this);

			Activate();
			EmitSignalPlayerEntered(this);
		}
		else if (body is Enemy enemy && enemy.AssociatedRoom != this)
		{
			enemy.AssociatedRoom?.UnregisterEnemy(enemy);
			RegisterEnemy(enemy);
		}
	}

	private void OnBodyExited(Node3D body)
	{
		//DebugManager.Trace($"{body.Name} entered {this.Name}");
		if (body is PlayerBody)
		{
			EmitSignalPlayerExited(this);
			Deactivate();
		}
	}


	public void OnRoundCompletion()
	{
		if (levelDoor != null)
		{
			levelDoor.SystemOpen();
		}
	}

	public void Activate()
	{
		IsActive = true;
		ShowRoom();

		// Pre-placed enemies are activated here
		foreach (var enemy in EnemiesInRoom)
		{
			enemy.Activate();
		}
	}

	public void Deactivate()

	{
		IsActive = false;

		if (!alwaysShow) HideRoom();


		// Deactivate any remaining enemies

		foreach (var enemy in EnemiesInRoom)

		{
			enemy.Deactivate();
		}
	}

	public void ShowRoom()
	{
		Visible = true;
	}

	public void HideRoom()
	{
		Visible = alwaysShow;
	}
}

using Godot;
using Godot.Collections;
using System.Collections.Generic;

namespace SpinalShatter;

[GlobalClass, Tool]
public partial class EnemySpawner : Node3D
{
    [Signal] public delegate void SpawningFinishedEventHandler();

    private float _spawnRadius = 10.0f;
    [Export] private float _spawnInterval = 1.0f;

    private LevelRoom _owningRoom;
    private Timer _spawnTimer;
    private Array<PackedScene> _enemiesToSpawn = new();
    private int _activeEnemyCount = 0;
    private readonly Godot.Collections.Dictionary<PackedScene, ObjectPoolManager<Node3D>> _pools = new();

    private MeshInstance3D radiusViewerInstance;
    private CylinderMesh radiusViewer;

    [Export(PropertyHint.Range, ".5, 20")]
    public float SpawnRadius
    {
        get => _spawnRadius;
        private set
        {
            _spawnRadius = Mathf.Max(value, .5f);
            SetRadius(_spawnRadius);
        }
    }


    [ExportToolButton("SetSpawnRadius", Icon = "CylinderShape3D")]
    public Callable SetSpawnRadiusButton => Callable.From(() => SetRadius(_spawnRadius));


    public override void _Ready()
    {
        if (Engine.IsEditorHint()) return;

        GetRadiusViewer();
        radiusViewerInstance.QueueFree();

        var parent = GetParent();
        while (parent is not LevelRoom)
        {
            parent = parent.GetParent();
        }
        _owningRoom = parent as LevelRoom;

        if (_owningRoom == null)
        {
            GD.PrintErr($"EnemySpawner '{Name}' is not a child of a LevelRoom. It will not function correctly.");
            SetProcess(false);
            return;
        }

        _spawnTimer = new Timer();
        AddChild(_spawnTimer);
        _spawnTimer.WaitTime = _spawnInterval;
        _spawnTimer.Timeout += OnSpawnTimerTimeout;
    }

    private void SetRadius(float newRadius)
    {
        if (!GetRadiusViewer()) return;

        radiusViewer.TopRadius = newRadius;
        radiusViewer.BottomRadius = newRadius;
    }

    public override void _Notification(int what)
    {
        if (this.IsInGame()) return;
        base._Notification(what);
        if (what == NotificationEnterTree)
        {
            SetRadius(_spawnRadius);
        }
    }

    private bool GetRadiusViewer()
    {
        if (!this.IsReady()) return false;

        radiusViewerInstance = GetNode<MeshInstance3D>("RadiusViewer");
        radiusViewer = radiusViewerInstance.Mesh as CylinderMesh;

        return radiusViewer != null;
    }

    public void StartSpawningWave(Array<PackedScene> enemies)
    {
        _enemiesToSpawn = new Array<PackedScene>(enemies);
        _enemiesToSpawn.Shuffle();
        _spawnTimer.Start();
    }

    private void OnSpawnTimerTimeout()
    {
        if (_enemiesToSpawn.Count == 0)
        {
            _spawnTimer.Stop();
            EmitSignalSpawningFinished();
            return;
        }

        var scene = _enemiesToSpawn.PopFront();
        if (scene != null)
        {
            Spawn(scene);
        }
    }

    /// <summary>
    /// Creates object pools for all the provided enemy scenes. This should be called
    /// before a round begins to ensure all needed enemies are ready.
    /// </summary>
    public void InitializePools(IEnumerable<PackedScene> enemyScenes)
    {
        foreach (var scene in enemyScenes)
        {
            if (scene == null || _pools.ContainsKey(scene)) continue;

            var newPool = new ObjectPoolManager<Node3D>
            {
                Scene = scene,
                Name = $"{scene.ResourcePath.GetFile().GetBaseName()}Pool"
            };

            // The ObjectPoolManager itself is a Node, so it can be added as a child
            // The PoolParent for the *pooled objects* should be the EnemySpawner itself,
            // or a dedicated container node within the spawner.
            AddChild(newPool); // Add the pool manager as a child of the spawner
            newPool.PoolParent = _owningRoom; // Pooled objects will be children of the owning room

            _pools[scene] = newPool;
        }
    }

    private void Spawn(PackedScene enemyScene)
    {
        if (enemyScene == null || !_pools.ContainsKey(enemyScene))
        {
            GD.PrintErr($"EnemySpawner: Scene is null or no pool exists for '{enemyScene?.ResourcePath}'.");
            return;
        }

        var pool = _pools[enemyScene];
        var newEnemyNode = pool.Get();

        if (newEnemyNode is Enemy newEnemy)
        {
            			newEnemy.OwningPool = pool;

            			float angle = (float)GD.Randf() * Mathf.Pi * 2;
            			float radius = Mathf.Sqrt((float)GD.Randf()) * SpawnRadius;
            			var randomOffset = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
            			newEnemy.GlobalPosition = GlobalPosition + new Vector3(randomOffset.X, 0, randomOffset.Y);

            			newEnemy.Activate();
            newEnemy.EnemyDied += OnEnemyDied;
            _owningRoom.RegisterEnemy(newEnemy);
            _activeEnemyCount++;

        }
        else
        {
            GD.PrintErr($"Failed to spawn node of type Enemy from scene '{enemyScene.ResourcePath}'. Node is type '{newEnemyNode.GetType().Name}'");
            // Fallback for nodes that aren't enemies, just place them
            GetParent().AddChild(newEnemyNode);
            newEnemyNode.GlobalPosition = this.GlobalPosition + Vector3.Up;
        }
    }

    private void OnEnemyDied(Enemy who)
    {
        _activeEnemyCount--;
        // It's good practice to disconnect signals from objects that might be reused
        who.EnemyDied -= OnEnemyDied;
    }
}

