	private void OnActionTimerTimeout()
	{
		if (_currentState == AIState.Patrolling)
		{
			Rotation = new Vector3(0, (float)GD.RandRange(0, Mathf.Pi * 2), 0);
			StartWalking();
		}
		else if (_currentState == AIState.Recovery)
		{
			ChangeState(AIState.Patrolling);
		}
	}

	private void WalkForward(ref Vector3 newVelocity)
	{
		newVelocity.X = -GlobalTransform.Basis.Z.X * WalkSpeed;
		newVelocity.Z = -GlobalTransform.Basis.Z.Z * WalkSpeed;
	}

	private void StartWalking()
	{
		_isWalking = true;
		timerWalk.WaitTime = GD.RandRange(MinWalkTime, MaxWalkTime);
		timerWalk.Start();
	}

	private void Wander(ref Vector3 newVelocity)
	{
		// Set velocity to move forward.
		if (Data.IsFlying)
		{
			newVelocity = -GlobalTransform.Basis.Z * WalkSpeed;
		}
		else
		{
			WalkForward(ref newVelocity);
		}

		// Check for wall collision and change direction for grounded enemies.
		if (Data.IsGrounded && IsOnWall())
		{
			var collision = GetLastSlideCollision();
			if (collision != null)
			{
				var forward = -GlobalTransform.Basis.Z.Normalized();
				var reflectDir = forward.Bounce(collision.GetNormal());
				LookAt(GlobalPosition + reflectDir, Vector3.Up);
			}
			else
			{
				// Fallback to random rotation if no collision data
				float randomAngle = (float)GD.RandRange(0, Mathf.Pi * 2);
				Rotation = new Vector3(0, randomAngle, 0);
			}
		}
	}

	private void OnWalkTimerTimeout()
	{
		StartWaiting();
	}

	private void StartWaiting()
	{
		_isWalking = false;
		timerAction.WaitTime = GD.RandRange(MinWaitTime, MaxWaitTime);
		timerAction.Start();
	}

	private void UpdateAnimation(float angleToPlayer)
	{
		string animName;
		bool flipH = false; // Default to not flipped

		// Determine animation based on angle
		if (angleToPlayer >= -22.5 && angleToPlayer <= 22.5) // Front cone
		{
			// HACK: we don't have straight sprites yet.
			animName = "Front";
			if (angleToPlayer < -1) // Player is to enemy's front-left
			{
				flipH = true;
			}
			else // Player is to enemy's front-right or directly front
			{
				flipH = false;
			}
		}
		else if (angleToPlayer > 22.5 && angleToPlayer <= 67.5) // Right side cone
		{
			animName = "Front_Diag";
			flipH = true; // Player is to enemy's right
		}
		else if (angleToPlayer < -22.5 && angleToPlayer >= -67.5) // Left side cone
		{
			animName = "Front_Diag";
			flipH = false; // Player is to enemy's left
		}
		else if (angleToPlayer > 67.5 && angleToPlayer <= 112.5) // Right side cone
		{
			animName = "Side";
			flipH = true; // Player is to enemy's right
		}
		else if (angleToPlayer < -67.5 && angleToPlayer >= -112.5) // Left side cone
		{
			animName = "Side";
			flipH = false; // Player is to enemy's left
		}
		else if (angleToPlayer > 112.5 && angleToPlayer <= 157.5) // Right side cone
		{
			animName = "Back_Diag";
			flipH = true; // Player is to enemy's right
		}
		else if (angleToPlayer < -112.5 && angleToPlayer >= -157.5) // Left side cone
		{
			animName = "Back_Diag";
			flipH = false; // Player is to enemy's left
		}
		else if (angleToPlayer > 157.5 && angleToPlayer <= 202.5) // Right side cone
		{
			animName = "Back";
			flipH = true; // Player is to enemy's right
		}
		else if (angleToPlayer < -157.5 && angleToPlayer >= -202.5) // Left side cone
		{
			animName = "Back";
			flipH = false; // Player is to enemy's left
		}
		else // Back cone
		{
			animName = "Back";
			if (angleToPlayer < 0) // Player is to enemy's back-left
			{
				flipH = false;
			}
			else // Player is to enemy's back-right
			{
				flipH = true;
			}
		}

		if (animPlayer.CurrentAnimation != animName)
		{
			animPlayer.Play(animName);
		}

		animatedSprite.FlipH = flipH;
		animatedSprite_Eye.FlipH = flipH;
	}

	// Update animation based on angle to player
	private void FacePlayer()
	{
		if (_player == null || _currentState == AIState.Dying) return;
		if (_currentState == AIState.Attacking) return;
		Vector3 toPlayer = _player.GlobalPosition - GlobalPosition;
		Vector3 enemyForward = -GlobalTransform.Basis.Z;
		float angleToPlayer = Mathf.RadToDeg(enemyForward.SignedAngleTo(toPlayer, Vector3.Up));
		UpdateAnimation(angleToPlayer);
	}

	public override void OnHurtboxBodyEntered(Node3D body)
	{
		if (isDying) return;

		base.OnHurtboxBodyEntered(body); // Handles damage + projectile destruction

		if (body is Projectile projectile && projectile.Owner != this)
		{
			projectile.OnEnemyHit();
		}
	}

	protected override void OnHurt(Vector3 sourcePosition, float damage)
	{
		base.OnHurt(sourcePosition, damage);
		ChangeState(AIState.Chasing);
	}

	public override void PlayOnHurtFX()
	{
		var tween = GetTree().CreateTween();
		tween.TweenProperty(animatedSprite, "modulate", Colors.Red, 0.1);
		tween.TweenProperty(animatedSprite, "modulate", Colors.White, 0.1);

		if (isDying) return;
		AudioManager.Play(AudioPlayer_SFX, (AudioFile)AudioData["Hurt"]);
	}

	public override void OnRanOutOfHealth()
	{
		// DebugManager.Debug($"Enemy: {Name} OnDied called.");
		ChangeState(AIState.Dying);
	}

	private void Despawn()
	{
		// DebugManager.Debug($"Enemy: {Name} Animation timer finished. Releasing enemy.");
		if (OwningPool != null) OwningPool.Release(this);
		else QueueFree();
	}

	private void TryToDie()
	{
		// DebugManager.Debug($"Enemy: {Name} TryToDie called. Current state: {_currentState}\n" +
		// 				   $"Death particles GlobalPosition before: {GlobalPosition}");

		if (_deathParticlesScene.Instantiate() is OneshotParticles deathParticles)
		{
			GetParent().AddChild(deathParticles);
			deathParticles.GlobalPosition = GlobalPosition;

			// DebugManager.Debug($"Enemy: {Name} Death particles GlobalPosition after: {deathParticles.GlobalPosition}");
			deathParticles.PlayParticles(Data.DeathParticleCount);
		}

		AudioManager.Play(AudioPlayer_Voice, (AudioFile)AudioData["Die"]);

		fogVolume.Visible = false;
		eyeSpotlight.Visible = false;
		animPlayer.Play("Die");
		timerBlink.Start();


		PickupManager.Instance.SpawnPickupAmount(PickupType.Mana, ManaAmountToDrop.GetRandomValue(),
			collisionShape.GlobalPosition);
		PickupManager.Instance.SpawnPickupAmount(PickupType.Money, MoneyAmountToDrop.GetRandomValue(),
			collisionShape.GlobalPosition);

		StopMoving();
		StopActionTimers();
		DisableCollisions();
		EmitSignalEnemyDied(this);

		timerPool.Start();
	}

	public override void Reset()
	{
		HealthComponent.Reset();

		// Stop all lingering timers from previous life
		StopActionTimers();

		// Kill any active tweens and reset visual state
		BlinkTween?.Kill();
		animatedSprite.Modulate = Colors.White;
		fogVolume.Visible = true;
		eyeSpotlight.Visible = true;

		// Reset state variables
		_player = null;
		_isWalking = false;

		Activate(); // This handles reenabling collisions and processing

		// Set initial state
		animPlayer.Stop(); // Stop any playing animation
		ChangeState(AIState.Idle, true);
	}

	public void Activate()
	{
		if (_isActive) return;

		_isActive = true;
		Visible = true;
		SetProcess(true);
		SetPhysicsProcess(true);

		EnableCollisions();
	}

	public void Deactivate()
	{
		if (!_isActive) return;
		_isActive = false;

		HideVisuals();

		StopProcessing();

		StopMoving();

		DisableCollisions();

		StopActionTimers();
	}

	private void HideVisuals()
	{
		Visible = false;
	}

	private void StopProcessing()
	{
		SetProcess(false);
		SetPhysicsProcess(false);
	}

	private void StopMoving()
	{
		Velocity = Vector3.Zero;
	}

	private void DisableCollisions()
	{
		// Remove enemy from its physics layers, making it undetectable.
		// this.RemoveCollisionLayer3D(LayerNames.PHYSICS_3D.ENEMY_COLLISION_NUM);
		// hurtbox.RemoveCollisionLayer3D(LayerNames.PHYSICS_3D.ENEMY_HURTBOX_NUM);
		// hurtbox.RemoveCollisionMask3D(LayerNames.PHYSICS_3D.PLAYER_HITBOX_NUM);
		// hurtbox.RemoveCollisionMask3D(LayerNames.PHYSICS_3D.PLAYER_PROJECTILE_NUM);

		hurtbox.SetDeferred("monitoring", false);
		hurtbox.SetDeferred("monitorable", false);

		if (meleeHitbox != null)
		{
			meleeHitbox.SetDeferred("monitoring", false);
			meleeHitbox.SetDeferred("monitorable", false);
		}
	}


	private void EnableCollisions()
	{
		// Restore enemy to its physics layers.
		// this.AddCollisionLayer3D(LayerNames.PHYSICS_3D.ENEMY_COLLISION_NUM);
		// hurtbox.AddCollisionLayer3D(LayerNames.PHYSICS_3D.ENEMY_HURTBOX_NUM);
		// hurtbox.AddCollisionMask3D(LayerNames.PHYSICS_3D.PLAYER_HITBOX_NUM);
		// hurtbox.AddCollisionMask3D(LayerNames.PHYSICS_3D.PLAYER_PROJECTILE_NUM);
		hurtbox.SetDeferred("monitoring", true);
		hurtbox.SetDeferred("monitorable", true);

		if (meleeHitbox != null)
		{
			meleeHitbox.SetDeferred("monitoring", true);
			meleeHitbox.SetDeferred("monitorable", true);
		}
	}

	private void StopActionTimers()
	{
		timerWalk?.Stop();
		timerAction?.Stop();
		timerAttackCooldown?.Stop();
		timerPool?.Stop();
		timerBlink?.Stop();
	}

	private void BlinkRoutine()
	{
		if (timerBlink.IsStopped()) return;

		double timeLeft = timerBlink.TimeLeft;

		float duration = timeLeft switch
		{
			<= 5.0 and > 3.0 => .5f,
			<= 3.0 and > 1.0 => 0.25f,
			<= 1.0 and > 0.0 => 0.125f,
			_ => 0
		};
		float alpha = timeLeft switch
		{
			<= 5.0 and > 3.0 => 0.5f,
			<= 3.0 and > 1.0 => 0.375f,
			<= 1.0 and > 0.0 => 0.25f,
			_ => 0
		};

		Blink(alpha, duration);
	}

	protected Tween BlinkTween;

	private void Blink(float alpha, float duration)
	{
		if (BlinkTween != null && BlinkTween.IsRunning() || animatedSprite == null) return;

		BlinkTween = CreateTween().SetLoops(2).SetTrans(Tween.TransitionType.Quart).SetEase(Tween.EaseType.InOut);
		BlinkTween.TweenProperty(animatedSprite, "modulate:a", alpha, duration / 2);
		BlinkTween.TweenProperty(animatedSprite, "modulate:a", 1.0f, duration / 2);
	}
}

using System.Collections.Generic;
using Elythia;
using Godot;


public partial class ObjectPoolManager<T> : Node where T : Node, new()
{
    private DebugLogger DEBUG;

    [Export] public PackedScene Scene { get; set; }
    [Export] public int PoolMaxSize { get; set; } = 1000;

    public Node PoolParent { get; set; }
    private readonly Queue<T> _readyPool = new();
    private int _activeObjects = 0;

    public override void _EnterTree()
    {
        DEBUG = new DebugLogger(this);

        if (PoolParent == null)
        {
            PoolParent = new Node { Name = $"{typeof(T).Name}Pool_Default" };
            GetTree().Root.AddChild(PoolParent);
        }
    }

    public void ClearPool()
    {
        foreach (var obj in _readyPool)
        {
            if (IsInstanceValid(obj))
            {
                obj.QueueFree();
            }
        }
        _readyPool.Clear();
        _activeObjects = 0;
    }

    public void Release(T obj)
    {
        if (_activeObjects <= 0 || !IsInstanceValid(obj))
        {
            // DEBUG.Info($"ObjectPoolManager: Attempted to release invalid or already released object: {obj?.Name ?? "null"}");
            return;
        }

        _activeObjects--;
        // DEBUG.Info($"ObjectPoolManager: Releasing object {obj.Name}. Active objects: {_activeObjects}");

        obj.SetDeferred("visible", false);
        obj.SetPhysicsProcess(false);
        obj.SetProcess(false);

        if (obj is Node3D node3D)
        {
            node3D.GlobalPosition = Vector3.Zero;
        }
        if (obj is Node2D node2D)
        {
            node2D.GlobalPosition = Vector2.Zero;
        }

        if (_readyPool.Count < PoolMaxSize)
        {
            _readyPool.Enqueue(obj);
            // DEBUG.Info($"ObjectPoolManager: Enqueued {obj.Name}. Ready pool size: {_readyPool.Count}");
        }
        else
        {
            obj.QueueFree();
            // DEBUG.Info($"ObjectPoolManager: Pool full, QueueFree() {obj.Name}.");
        }
    }

    public T Get()
    {
        if (_activeObjects >= PoolMaxSize)
        {
            // DEBUG.Info($"ObjectPoolManager: Pool full, cannot get new object. Active objects: {_activeObjects}");
            return null;
        }

        T obj;

        if (_readyPool.Count > 0)
        {
            obj = _readyPool.Dequeue();
            // DEBUG.Info($"ObjectPoolManager: Dequeued existing object {obj.Name}. Ready pool size: {_readyPool.Count}");
        }
        else
        {
            if (Scene == null)
            {
                GD.PrintErr($"ObjectPoolManager for {typeof(T).Name} has no scene packed!");
                return null;
            }
            obj = Scene.Instantiate<T>();
            PoolParent.AddChild(obj);
            // DEBUG.Info($"ObjectPoolManager: Instantiated new object {obj.Name}.");
        }

        if (obj.HasMethod("Reset"))
        {
	        obj.Call("Reset");
        }

        obj.SetProcess(true);
        obj.SetPhysicsProcess(true);
        obj.SetDeferred("visible", true);

        _activeObjects++;
        // DEBUG.Info($"ObjectPoolManager: Got object {obj.Name}. Active objects: {_activeObjects}");

        return obj;
    }
}

