	private float _gravity => Constants.GRAVITY;


	public override void _Ready()
	{
		base._Ready(); // GetComponents, ConnectEvents

		if (Data == null)
		{
			DebugManager.Error($"Enemy '{Name}' is missing EnemyData!");
		}
		else
		{
